//! Numeric-to-string helpers shared by the progress types.

/// Default number of fractional digits used when a caller does not ask for a
/// specific precision.
pub const DEFAULT_PRECISION: usize = 1;

/// Stateless namespace for display formatting, mirroring `indicators::Format`.
pub struct Format;

impl Format {
    /// Renders a 0.0..=1.0 ratio as a percentage with [`DEFAULT_PRECISION`]
    /// fractional digits, e.g. `0.33` -> `"33.0%"`.
    pub fn percentage(value: f32) -> String {
        Self::percentage_with_precision(value, DEFAULT_PRECISION)
    }

    /// Renders a 0.0..=1.0 ratio as a percentage with `precision` fractional
    /// digits, e.g. `(0.66, 2)` -> `"66.00%"`.
    ///
    /// The ratio is widened to `f64` before scaling so the multiply matches the
    /// usual C++ promotion to `double`.
    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        format!("{:.*}%", precision, f64::from(value) * 100.0)
    }

    /// Renders a `progress`/`total` pair as `"1/3"`.
    pub fn ratio(progress: i64, total: i64) -> String {
        format!("{}/{}", progress, total)
    }
}

/// Divides `progress` by `total` as a ratio, yielding `0.0` when `total` is not
/// positive so callers never surface `inf` or `NaN`.
pub fn fraction(progress: i64, total: i64) -> f32 {
    if total <= 0 {
        return 0.0;
    }
    (progress as f64 / total as f64) as f32
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn percentage_uses_one_digit_by_default() {
        assert_eq!(Format::percentage(0.33), "33.0%");
        assert_eq!(Format::percentage(0.3), "30.0%");
    }

    #[test]
    fn percentage_honors_explicit_precision() {
        assert_eq!(Format::percentage_with_precision(0.66, 2), "66.00%");
        assert_eq!(Format::percentage_with_precision(0.66, 0), "66%");
    }

    #[test]
    fn ratio_renders_progress_over_total() {
        assert_eq!(Format::ratio(1, 3), "1/3");
    }

    #[test]
    fn fraction_guards_non_positive_total() {
        assert_eq!(fraction(1, 0), 0.0);
        assert_eq!(fraction(1, -3), 0.0);
        assert_eq!(fraction(60, 200), 0.3);
    }
}

