//! Chainable builder that renders a progress ratio as a percentage string.

use super::format::{fraction, Format};

/// Total assumed by a freshly constructed builder, so `build()` reports a
/// percentage even when only `set_progress` is called.
const DEFAULT_TOTAL: i64 = 100;

/// Accumulates progress state, mirroring `indicators::ProgressBuilder`.
pub struct ProgressBuilder {
    progress: i64,
    total: i64,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        ProgressBuilder {
            progress: 0,
            total: DEFAULT_TOTAL,
        }
    }

    pub fn set_progress(&mut self, progress: i64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: i64) -> &mut Self {
        self.total = total;
        self
    }

    pub fn progress(&self) -> i64 {
        self.progress
    }

    pub fn total(&self) -> i64 {
        self.total
    }

    /// Renders the accumulated state, e.g. 60 of 200 -> `"30.0%"`.
    pub fn build(&self) -> String {
        Format::percentage(fraction(self.progress, self.total))
    }
}

impl Default for ProgressBuilder {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn setters_chain_and_build_renders_percentage() {
        let mut builder = ProgressBuilder::new();
        builder.set_progress(60).set_total(200);
        assert_eq!(builder.build(), "30.0%");
    }

    #[test]
    fn default_total_is_a_hundred() {
        let mut builder = ProgressBuilder::new();
        builder.set_progress(42);
        assert_eq!(builder.build(), "42.0%");
    }
}

