//! Multi-stage progress tracker.

use super::format::{fraction, Format};

/// Named stages plus a progress counter, mirroring
/// `indicators::ProgressTracker`.
pub struct ProgressTracker {
    stages: Vec<String>,
    progress: i64,
    total: i64,
}

impl ProgressTracker {
    pub fn new() -> Self {
        ProgressTracker {
            stages: Vec::new(),
            progress: 0,
            total: 0,
        }
    }

    pub fn add_stage(&mut self, name: &str) -> &mut Self {
        self.stages.push(name.to_string());
        self
    }

    pub fn set_progress(&mut self, progress: i64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: i64) -> &mut Self {
        self.total = total;
        self
    }

    pub fn stages(&self) -> &[String] {
        &self.stages
    }

    /// The stage the counter currently points at, or `None` once progress has
    /// run past the registered stages.
    pub fn current_stage(&self) -> Option<&str> {
        self.stages
            .get(self.progress.max(0) as usize)
            .map(String::as_str)
    }

    /// Renders the counter as `"1/3"`.
    pub fn get_progress(&self) -> String {
        Format::ratio(self.progress, self.total)
    }

    /// Renders the counter as a percentage, e.g. 1 of 3 -> `"33.3%"`.
    pub fn get_percentage(&self) -> String {
        Format::percentage(fraction(self.progress, self.total))
    }
}

impl Default for ProgressTracker {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn three_stage_tracker() -> ProgressTracker {
        let mut tracker = ProgressTracker::new();
        tracker
            .add_stage("Downloading")
            .add_stage("Processing")
            .add_stage("Saving");
        tracker.set_progress(1);
        tracker.set_total(3);
        tracker
    }

    #[test]
    fn renders_ratio_and_percentage() {
        let tracker = three_stage_tracker();
        assert_eq!(tracker.get_progress(), "1/3");
        assert_eq!(tracker.get_percentage(), "33.3%");
    }

    #[test]
    fn tracks_registered_stages() {
        let tracker = three_stage_tracker();
        assert_eq!(tracker.stages().len(), 3);
        assert_eq!(tracker.current_stage(), Some("Processing"));
    }

    #[test]
    fn empty_tracker_avoids_divide_by_zero() {
        let tracker = ProgressTracker::new();
        assert_eq!(tracker.get_progress(), "0/0");
        assert_eq!(tracker.get_percentage(), "0.0%");
        assert_eq!(tracker.current_stage(), None);
    }
}

